class Solution {
    public String makeSmallestPalindrome(String s){
        char[] value=s.toCharArray();
        for(int left=0,right=value.length-1;left<right;left++,right--){
            char smaller=(char)Math.min(value[left],value[right]);
            value[left]=value[right]=smaller;
        }
        return new String(value);
    }
}

code.kotlin:
class Solution {
    fun makeSmallestPalindrome(s:String):String{
        val value=s.toCharArray();
        var left=0;
        var right=value.lastIndex;
        while(left<right){
            val smaller=minOf(value[left],value[right]);
            value[left]=smaller;
            value[right]=smaller;
            left++;
            right--
        };
        return String(value)
    }
}

